// Regenerates every TEXT artifact derived from branding/pengu.svg: the rounded
// and frameless SVG variants and the Android adaptive-icon XML. The geometry is
// read from the master, so the paths are never typed twice.
//
//   node scripts/gen_brand_icons.mjs
//
// Edit `branding/pengu.svg` and re-run this; never edit the generated files.
// The rasters (store PNG, launcher mipmaps, desktop ladder, .ico) are committed
// outputs — the commands to rebuild them are printed at the end.

import { readFileSync, writeFileSync } from "node:fs";

const MASTER = "branding/pengu.svg";
const RES = "app/androidApp/src/main/res";
const SCALE = 1.78; // the frameless variant: mark at ~85 % of the canvas
const master = readFileSync(MASTER, "utf8");

const grab = (re, what) => {
  const m = re.exec(master);
  if (!m) throw new Error(`${MASTER}: ${what} not found`);
  return m;
};

// ---- geometry: one source ----------------------------------------------------
const [, beakD, beakStroke] = grab(
  /<path id="beak" d="([^"]+)"[^>]*stroke-width="([^"]+)"/,
  '<path id="beak">',
);
const upperPoints = grab(/<clipPath id="upper"><polygon points="([^"]+)"/, "upper clip")[1];
const [, lineX1, lineY1, lineX2, lineY2, splitColor, splitWidth] = grab(
  /<line x1="([^"]+)" y1="([^"]+)" x2="([^"]+)" y2="([^"]+)"\s+stroke="([^"]+)" stroke-width="([^"]+)"/,
  "split line",
);
const tile = grab(/<rect width="1024" height="1024" fill="(#[0-9A-Fa-f]+)"\/>/, "tile rect")[1];
const tones = [...master.matchAll(/<use href="#beak" fill="(#[0-9A-Fa-f]+)"/g)].map((m) => m[1]);
if (tones.length !== 2) throw new Error(`${MASTER}: expected two mandible tones`);
const [lowerTone, upperTone] = tones;

// the beak's stroked bounds, for the split line in the Android vector (which
// cannot use a mask: its line ends on the tip's round cap instead)
const left = 335 - Number(beakStroke) / 2 - 2;
const right = 702 + Number(beakStroke) / 2 - 1;
const yAt = (x) =>
  Number(lineY1) + ((Number(lineY2) - Number(lineY1)) / (Number(lineX2) - Number(lineX1))) * (x - Number(lineX1));
const androidSplit = `M${left},${yAt(left).toFixed(1)} L${right},${yAt(right).toFixed(1)}`;
const clipD = `M${upperPoints.split(" ").join(" L")} Z`;

const header = (what) =>
  `<!-- Generated by scripts/gen_brand_icons.mjs from ${MASTER} — ${what}.\n` +
  `     Edit the master and re-run the script; this file is overwritten. -->`;

// ---- 1. rounded: same art, 22 % corners, transparent outside the tile --------
writeFileSync(
  "branding/pengu-rounded.svg",
  master
    .replace(`<rect width="1024" height="1024" fill="${tile}"/>`, `<rect width="1024" height="1024" rx="224" fill="${tile}"/>`)
    .replace("<svg ", `${header("the 22 % corner-radius variant")}\n<svg `),
);

// ---- 2. frameless: no tile, bigger mark, one-device-pixel outline -----------
const frameless = (size) => {
  const w = (1024 / size / SCALE).toFixed(1);
  return `${header(`the frameless variant, outline of one device pixel at ${size} px`)}
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1024 1024" width="512" height="512" role="img" aria-labelledby="t">
  <title id="t">Pengu</title>
  <desc id="d">A play button with a beak's two mandibles.</desc>
  <defs>
    <path id="beak" d="${beakD}" stroke-width="${beakStroke}" stroke-linejoin="round"/>
    <clipPath id="upper"><polygon points="${upperPoints}"/></clipPath>
    <mask id="beakMask" maskUnits="userSpaceOnUse" x="0" y="0" width="1024" height="1024">
      <path d="${beakD}" fill="#FFFFFF" stroke="#FFFFFF" stroke-width="${beakStroke}" stroke-linejoin="round"/>
    </mask>
  </defs>

  <g transform="translate(502 512) scale(${SCALE}) translate(-512 -512)">
    <path d="${beakD}" fill="${tile}" stroke="${tile}" stroke-width="${64 + 2 * Number(w)}"
          stroke-linejoin="round"/>
    <use href="#beak" fill="${lowerTone}" stroke="${lowerTone}"/>
    <use href="#beak" fill="${upperTone}" stroke="${upperTone}" clip-path="url(#upper)"/>
    <line x1="${lineX1}" y1="${lineY1}" x2="${lineX2}" y2="${lineY2}"
          stroke="${splitColor}" stroke-width="${splitWidth}" mask="url(#beakMask)"/>
  </g>
</svg>
`;
};
writeFileSync("branding/pengu-frameless.svg", frameless(256));

// ---- 3. Android adaptive icon ----------------------------------------------
writeFileSync(
  `${RES}/drawable/ic_launcher_background.xml`,
  `<?xml version="1.0" encoding="utf-8"?>
${header("the adaptive-icon background")}
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="108dp"
    android:height="108dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
    <path android:pathData="M0,0h108v108h-108z" android:fillColor="${tile}" />
</vector>
`,
);

writeFileSync(
  `${RES}/drawable-v24/ic_launcher_foreground.xml`,
  `<?xml version="1.0" encoding="utf-8"?>
${header("the adaptive-icon foreground")}
<!-- Scaled so the mark's circumscribed circle fits the 72 dp mask: the triangle's
     corners touch the edge without being cropped on any shape. No masks in
     VectorDrawable, so the split line ends on the tip's round cap. -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="108dp"
    android:height="108dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
    <group
        android:translateX="54"
        android:translateY="54"
        android:scaleX="0.0732"
        android:scaleY="0.0732">
        <group android:translateX="-512" android:translateY="-512">
            <path
                android:pathData="${beakD}"
                android:strokeColor="${lowerTone}"
                android:strokeWidth="${beakStroke}"
                android:strokeLineJoin="round"
                android:fillColor="${lowerTone}" />
            <group>
                <clip-path android:pathData="${clipD}" />
                <path
                    android:pathData="${beakD}"
                    android:strokeColor="${upperTone}"
                    android:strokeWidth="${beakStroke}"
                    android:strokeLineJoin="round"
                    android:fillColor="${upperTone}" />
            </group>
            <path
                android:pathData="${androidSplit}"
                android:strokeColor="${splitColor}"
                android:strokeWidth="${splitWidth}"
                android:strokeLineCap="round" />
        </group>
    </group>
</vector>
`,
);

console.log("wrote branding/pengu-rounded.svg");
console.log("wrote branding/pengu-frameless.svg");
console.log(`wrote ${RES}/drawable/ic_launcher_background.xml`);
console.log(`wrote ${RES}/drawable-v24/ic_launcher_foreground.xml`);
console.log(`
Rasters are committed outputs; rebuild them with:

  npx sharp-cli -i branding/pengu.svg -o branding/pengu.png resize 512 512
  npx sharp-cli -i branding/pengu-rounded.svg -o branding/pengu-rounded.png resize 512 512
  # launcher mipmaps (48-192), desktop ladder (16-256) and pengu.ico: see
  # branding/README.md`);
